import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  TextInput,
  StyleSheet,
  Alert,
  ScrollView,
  TouchableOpacity,
  KeyboardAvoidingView,
  Platform,
  Image,
  Animated,
} from 'react-native';
import { setDoc, doc, getFirestore, updateDoc, increment } from 'firebase/firestore';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { useNavigation } from '@react-navigation/native';
import { auth } from '../services/firebaseConfig';
import { MaterialIcons } from '@expo/vector-icons';

// Mapeamento de emojis coloridos para cada campo
const iconesPorCampo: Record<keyof Escala, string> = {
  data: '📅',
  responsavel: '🧑‍💼',
  violao: '🎸',
  teclado: '🎹',
  bateria: '🥁',
  guitarra: '🎸',
  contrabaixo: '🪕',
  vocal: '🎙️',
  backVocal1: '🎤',
  backVocal2: '🎤',
  backVocal3: '🎤',
  backVocal4: '🎤',
  som: '🔊',
  projecao: '🖥️',
  midia1: '📱',
  midia2: '📱',
  midia3: '🎥',
  midia4: '📸',
};

const db = getFirestore();

const CORES_UNIFORME = [
  '#FFFFFF',
  '#111827',
  '#2563EB',
  '#16A34A',
  '#DC2626',
  '#F97316',
  '#FACC15',
  '#7C3AED',
  '#EC4899',
  '#6B7280',
];

interface Escala {
  data: string;
  responsavel: string;
  violao: string;
  teclado: string;
  bateria: string;
  guitarra: string;
  contrabaixo: string;
  vocal: string;
  backVocal1: string;
  backVocal2: string;
  backVocal3: string;
  backVocal4: string;
  som: string;
  projecao: string;
  midia1: string;
  midia2: string;
  midia3: string;
  midia4: string;
}

const estadoInicial: Escala = {
  data: '',
  responsavel: '',
  violao: '',
  teclado: '',
  bateria: '',
  guitarra: '',
  contrabaixo: '',
  vocal: '',
  backVocal1: '',
  backVocal2: '',
  backVocal3: '',
  backVocal4: '',
  som: '',
  projecao: '',
  midia1: '',
  midia2: '',
  midia3: '',
  midia4: '',
};

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
];

const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

export default function TelaCriarEscala(): JSX.Element {
  const navigation = useNavigation();
  const [escala, setEscala] = useState<Escala>(estadoInicial);
  const [corCamiseta, setCorCamiseta] = useState('#FFFFFF');
  const [corCalcaSaia, setCorCalcaSaia] = useState('#111827');
  const [uidAtual, setUidAtual] = useState<string | null>(null);

  // Animação de alto relevo para o botão
  const saveAnim = React.useRef(new Animated.Value(1)).current;

  useEffect(() => {
    setUidAtual(auth.currentUser?.uid ?? null);
  }, []);

  const handleChange = (campo: keyof Escala, valor: string) => {
    if (campo === 'data') {
      let cleaned = valor.replace(/\D/g, '');
      if (cleaned.length > 8) cleaned = cleaned.slice(0, 8);
      let formatted = cleaned;
      if (cleaned.length > 4) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2, 4)}/${cleaned.slice(4)}`;
      } else if (cleaned.length > 2) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2)}`;
      }
      setEscala(prev => ({ ...prev, [campo]: formatted }));
    } else {
      setEscala(prev => ({ ...prev, [campo]: valor }));
    }
  };

  const salvarEscala = async () => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) {
      Alert.alert('Acesso negado', 'Você não tem permissão para criar escalas.');
      return;
    }

    if (!escala.data || !escala.responsavel) {
      Alert.alert('Erro', 'Preencha pelo menos Data e Responsável.');
      return;
    }

    const idDoc = escala.data.replace(/\//g, '-');

    try {
      await setDoc(
        doc(db, 'escalas', idDoc),
        {
          ...escala,
          uniforme: {
            corCamiseta,
            corCalcaSaia,
          },
          criadoEm: new Date(),
        }
      );
      Alert.alert('Sucesso', 'Escala criada com sucesso!');
        // incrementa contador remoto (para todos os usuários) e local como fallback
        const metaRef = doc(db, 'meta', 'escalas');
        try {
          await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
        } catch (e) {
          // se o doc não existir, cria com valor 1
          try {
            await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
          } catch (err) {
            console.log('Erro ao atualizar contador remoto de escalas', err);
          }
        }
        try {
          const cur = await AsyncStorage.getItem('nova_escala');
          const num = cur ? parseInt(cur, 10) || 0 : 0;
          const novo = num + 1;
          await AsyncStorage.setItem('nova_escala', String(novo));
          await Notifications.setBadgeCountAsync(novo);
        } catch (e) {
          console.log('Não foi possível setar badge/flag local', e);
        }
      navigation.goBack();
    } catch (error) {
      console.error('Erro ao salvar escala:', error);
      Alert.alert('Erro', 'Não foi possível salvar a escala.');
    }
  };

  const formatarLabel = (key: keyof Escala): string => {
    switch (key) {
      case 'data': return 'Data';
      case 'responsavel': return 'Responsável';
      case 'violao': return 'Violão';
      case 'teclado': return 'Teclado';
      case 'bateria': return 'Bateria';
      case 'guitarra': return 'Guitarra';
      case 'contrabaixo': return 'Contrabaixo';
      case 'vocal': return 'Vocal';
      case 'backVocal1': return 'Back Vocal 1';
      case 'backVocal2': return 'Back Vocal 2';
      case 'backVocal3': return 'Back Vocal 3';
      case 'backVocal4': return 'Back Vocal 4';
      case 'som': return 'Som';
      case 'projecao': return 'Projeção';
      case 'midia1': return 'Mídia 1';
      case 'midia2': return 'Mídia 2';
      case 'midia3': return 'Mídia 3';
      case 'midia4': return 'Mídia 4';
      default: return String(key).charAt(0).toUpperCase() + String(key).slice(1);
    }
  };

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  // Efeito de alto relevo no botão
  const handlePressIn = () => {
    Animated.spring(saveAnim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = () => {
    Animated.spring(saveAnim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <View style={styles.bg}>
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <ScrollView
          contentContainerStyle={styles.container}
          keyboardShouldPersistTaps="handled"
        >
          {/* HEADER NEUMÓRFICO PERSONALIZADO */}
          <View style={styles.headerNeumorphic}>
            <View style={styles.headerRow}>
              {/* Botão Home à esquerda */}
              <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.navigate('Inicio')}>
				<Image
				  source={{ uri: 'https://img.icons8.com/?size=100&id=bIwuxbfp2H2N&format=png&color=000000.png' }}
				  style={styles.headerIcon}
				/>
			  </TouchableOpacity>

              {/* Botão Nova Escala centralizado */}
              <View style={styles.headerCenterBox}>
                <TouchableOpacity
                  style={styles.novaEscalaBtn}
                  onPress={() => Alert.alert('Nova Escala', 'Ação de nova escala!')}
                  activeOpacity={0.85}
                >
                  <Text style={styles.novaEscalaText}>Nova Escala</Text>
                </TouchableOpacity>
              </View>

              {/* Botão Voltar à direita */}
              <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.goBack()}>
				<Image
				  source={{ uri: 'https://img.icons8.com/?size=100&id=CFDbApIER33U&format=png&color=000000.png' }}
				  style={styles.headerIcon}
				/>
			  </TouchableOpacity>
            </View>
          </View>
          {/* FIM HEADER */}

          <NeumorphicContainer style={styles.card}>
            {Object.keys(escala).map((chave) => {
              const campo = chave as keyof Escala;
              return (
                <NeumorphicContainer key={campo} style={styles.inputGroup}>
                  <View style={styles.labelRow}>
                    <Text style={styles.emoji}>{iconesPorCampo[campo]}</Text>
                    <Text style={styles.label}>{formatarLabel(campo)}</Text>
                  </View>
                  <TextInput
                    style={styles.input}
                    value={escala[campo]}
                    onChangeText={(texto) => handleChange(campo, texto)}
                    placeholder={campo === 'data' ? 'dd/mm/aaaa' : undefined}
                    autoCapitalize={campo === 'responsavel' ? 'words' : 'none'}
                    editable={permitido}
                    placeholderTextColor="#90caf9"
                    keyboardType={campo === 'data' ? 'numeric' : 'default'}
                    maxLength={campo === 'data' ? 10 : undefined}
                  />
                </NeumorphicContainer>
              );
            })}
            <NeumorphicContainer style={styles.uniformeBox}>
              <View style={styles.labelRow}>
                <MaterialIcons name="checkroom" size={22} color="#ff9800" style={{ marginRight: 8 }} />
                <Text style={styles.label}>Uniforme do culto</Text>
              </View>

              <Text style={styles.uniformeLabel}>Cor da camiseta</Text>
              <View style={styles.coresLinha}>
                {CORES_UNIFORME.map(cor => (
                  <TouchableOpacity
                    key={`camiseta-${cor}`}
                    style={[
                      styles.corOpcao,
                      { backgroundColor: cor },
                      corCamiseta === cor && styles.corOpcaoSelecionada,
                    ]}
                    onPress={() => setCorCamiseta(cor)}
                    disabled={!permitido}
                    activeOpacity={0.8}
                  />
                ))}
              </View>

              <Text style={styles.uniformeLabel}>Cor da calca ou saia</Text>
              <View style={styles.coresLinha}>
                {CORES_UNIFORME.map(cor => (
                  <TouchableOpacity
                    key={`calca-${cor}`}
                    style={[
                      styles.corOpcao,
                      { backgroundColor: cor },
                      corCalcaSaia === cor && styles.corOpcaoSelecionada,
                    ]}
                    onPress={() => setCorCalcaSaia(cor)}
                    disabled={!permitido}
                    activeOpacity={0.8}
                  />
                ))}
              </View>
            </NeumorphicContainer>
            <Animated.View style={{ transform: [{ scale: saveAnim }] }}>
              <TouchableOpacity
                style={[styles.saveButton, !permitido && styles.saveButtonDisabled]}
                onPress={salvarEscala}
                disabled={!permitido}
                onPressIn={handlePressIn}
                onPressOut={handlePressOut}
                activeOpacity={0.85}
              >
                <Text style={styles.saveButtonText}>Salvar Escala</Text>
              </TouchableOpacity>
            </Animated.View>
            {!permitido && (
              <Text style={styles.permissaoAviso}>
                Apenas usuários autorizados podem criar escalas.
              </Text>
            )}
          </NeumorphicContainer>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

